def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    x = [float(v) for v in history if math.isfinite(float(v))]
    if horizon <= 0:
        return []
    if not x:
        return [0.0] * horizon
    p = 24
    def_value = float(statistics.median(x[-min(len(x), p):]))
    candidates = ['seasonal', 'median', 'blend']
    scores = {c: 0.0 for c in candidates}
    counts = {c: 0 for c in candidates}
    start = max(p, len(x) - min(4 * p, len(x) - p))
    for t in range(start, len(x)):
        train = x[:t]
        recent = float(statistics.median(train[-min(p, len(train)):]))
        seasonal = train[t - p] if t >= p else recent
        preds = {'seasonal': seasonal, 'median': recent, 'blend': 0.75 * seasonal + 0.25 * recent}
        for c in candidates:
            scores[c] += abs(x[t] - preds[c])
            counts[c] += 1
    best = min(candidates, key=lambda c: scores[c] / max(1, counts[c]))
    out = []
    for k in range(horizon):
        seasonal = x[len(x) - p + (k % p)] if len(x) >= p else def_value
        recent = def_value
        if best == 'seasonal':
            pred = seasonal
        elif best == 'blend':
            pred = 0.75 * seasonal + 0.25 * recent
        else:
            pred = recent
        out.append(float(pred))
    return out
